<?php declare(strict_types=1); session_start(); if(empty($_SESSION['user'])||($_SESSION['user']['rol']??'')!=='superadmin'){http_response_code(403);exit('Acceso no autorizado.');}$nombre=trim((string)($_POST['nombre']??''));$email=trim((string)($_POST['email']??''));$password=(string)($_POST['password']??'');$rol=(string)($_POST['rol']??'');$tienda=(int)($_POST['tienda_id']??0);$telefono=trim((string)($_POST['telefono']??''));if($nombre===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8||!in_array($rol,['admin_tienda','vendedor','repartidor'],true)||!$tienda){http_response_code(400);exit('Completa correctamente los datos.');}$config=require __DIR__.'/config.php';try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$q=$pdo->prepare('INSERT INTO usuarios (tienda_id,nombre,email,password_hash,rol,telefono) VALUES (?,?,?,?,?,?)');$q->execute([$tienda,$nombre,$email,password_hash($password,PASSWORD_DEFAULT),$rol,$telefono]);header('Location: usuarios-admin.php?created=1');}catch(PDOException $e){if($e->getCode()==='23000')exit('Ese correo ya está registrado.');http_response_code(500);exit('No se pudo crear el usuario.');}
